properties.property:
local BlockPlayer = require "actions/BlockPlayer"
local Do = require "actions/Do"
local Animate = require "actions/Animate"

return function(self)
    local isOn = self.sprite.selected == "on"

    return BlockPlayer {
        Do(function()
            local lightLayer = self.scene:findLayer("light")
            lightLayer.opacity = isOn and 0.5 or 0.0
        end),
        Animate(self.sprite, isOn and "off" or "on")
    }
end

